-- KAI pgAdmin production migration packet: 02V verification after 02 (client_admin sensitivity review)
-- READ-ONLY. One SELECT statement; it changes nothing and inserts nothing.
-- Proves the migration produced exactly its intended objects; role and vocabulary rules are
-- evaluated by running the live CHECK expressions against literal values (query_to_xml), not by
-- inserting rows. Last row OVERALL must be PASS before the next step.
-- Generated by scripts/kai-sprint2-pgadmin-production-packet-build.js from
--   artifacts/kai-db-reconciliation-2026-09-16/PRODUCTION_KAI_SCHEMA.json (owner pgAdmin capture, 2026-09-16) and
--   KAI_PGADMIN_PRODUCTION_MIGRATION_PACKET/support/expected_post_migration_catalog_pg16.json.
-- Run it in the pgAdmin Query Tool (Execute script, F5). Read the Data Output grid.
WITH
checks(seq, section, check_id, status, expected, observed, detail) AS (
  SELECT 100, 'V02', 'V02.1',
              CASE WHEN (SELECT md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', ''))
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND con.conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') = '16d5698f45a58b56226dd2a144839e09' THEN 'PASS' ELSE 'FAIL' END, 'CHECK (decided_by_role = ANY (ARRAY[''gk_admin''::text, ''gk_operator''::text, ''gk_reviewer''::text, ''client_admin''::text]))', coalesce((SELECT regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(con.oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')
       FROM pg_constraint con WHERE con.conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND con.conname = 'intake_sensitivity_review_decisions_b1a_02_role_check'), '(absent)'), 'Role CHECK admits client_admin in addition to the three GK roles'
  UNION ALL
  SELECT 101, 'V02', 'V02.2',
           CASE WHEN m.bad IS NULL THEN 'PASS' ELSE 'FAIL' END,
           '6 combinations: gk_admin, gk_operator, gk_reviewer, client_admin accepted; all others rejected',
           CASE WHEN m.bad IS NULL THEN '6/6 combinations behave as expected' ELSE 'mismatched: ' || m.bad END,
           'Sensitivity-decision roles: client_admin and GK roles accepted; client_reviewer/client_contributor rejected'
      FROM (SELECT concat_ws('; ', CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') || ') AS ok FROM (VALUES (' || quote_literal('gk_admin') || '::text' || ')) AS v(decided_by_role)', true, true, '')))[1]::text) = 'true' THEN NULL ELSE 'gk_admin expected accepted' END,
                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') || ') AS ok FROM (VALUES (' || quote_literal('gk_operator') || '::text' || ')) AS v(decided_by_role)', true, true, '')))[1]::text) = 'true' THEN NULL ELSE 'gk_operator expected accepted' END,
                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') || ') AS ok FROM (VALUES (' || quote_literal('gk_reviewer') || '::text' || ')) AS v(decided_by_role)', true, true, '')))[1]::text) = 'true' THEN NULL ELSE 'gk_reviewer expected accepted' END,
                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') || ') AS ok FROM (VALUES (' || quote_literal('client_admin') || '::text' || ')) AS v(decided_by_role)', true, true, '')))[1]::text) = 'true' THEN NULL ELSE 'client_admin expected accepted' END,
                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') || ') AS ok FROM (VALUES (' || quote_literal('client_reviewer') || '::text' || ')) AS v(decided_by_role)', true, true, '')))[1]::text) = 'false' THEN NULL ELSE 'client_reviewer expected rejected' END,
                                     CASE WHEN (SELECT (xpath('/row/ok/text()', query_to_xml(
        'SELECT (' || (SELECT 'coalesce((' || pg_get_expr(conbin, conrelid) || '), true)' FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_sensitivity_review_decisions') AND conname = 'intake_sensitivity_review_decisions_b1a_02_role_check') || ') AS ok FROM (VALUES (' || quote_literal('client_contributor') || '::text' || ')) AS v(decided_by_role)', true, true, '')))[1]::text) = 'false' THEN NULL ELSE 'client_contributor expected rejected' END) AS raw) r
      CROSS JOIN LATERAL (SELECT nullif(r.raw, '') AS bad) m
)
SELECT seq, section, check_id, status, expected, observed, detail FROM checks
UNION ALL
SELECT 999, 'OVERALL', 'OVERALL',
       CASE WHEN EXISTS (SELECT 1 FROM checks WHERE status NOT IN ('PASS', 'INFO', 'WARN')) THEN 'FAIL' ELSE 'PASS' END,
       'every row PASS (migration 02 verified)',
       coalesce('failing rows: ' || (SELECT string_agg(check_id, ', ' ORDER BY seq) FROM checks WHERE status NOT IN ('PASS', 'INFO', 'WARN')), 'all rows PASS')
         || coalesce('; WARN: ' || (SELECT string_agg(check_id, ', ' ORDER BY seq) FROM checks WHERE status = 'WARN'), ''),
       CASE WHEN EXISTS (SELECT 1 FROM checks WHERE status NOT IN ('PASS', 'INFO', 'WARN'))
            THEN 'STOP. Do not run the next file. Export this grid as CSV and send it back.' ELSE 'Verified.' END
ORDER BY seq;
